function token(){try{const j=JSON.parse(localStorage.getItem(STORE)||'null');return j?.access_token||j?.currentSession?.access_token||j?.session?.access_token||''}catch{return''}}
async function api(action,body={},auth=false){const headers={apikey:KEY,'Content-Type':'application/json'};const t=token();if(auth){if(!t)throw Error('Sign in again to manage news.');headers.Authorization='Bearer '+t}const r=await fetch(API,{method:'POST',headers,body:JSON.stringify({action,...body})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'News request failed');return d}
function role(){return ($('roleBadge')?.textContent||'').trim().toLowerCase()}
function style(){if($('dxNewsStyle'))return;const s=document.createElement('style');s.id='dxNewsStyle';s.textContent=`#dxNewsBanner{display:none;margin:0 0 14px;padding:14px 15px;border-radius:18px;background:linear-gradient(135deg,var(--card),var(--navy2));color:var(--white);box-shadow:0 8px 22px #0003;border:1px solid color-mix(in srgb,var(--yellow) 42%,transparent)}#dxNewsBanner.show{display:block}#dxNewsBanner .dx-news-label{font-size:11px;font-weight:950;letter-spacing:.08em;text-transform:uppercase;color:var(--yellow)}#dxNewsBanner .dx-news-message{font-size:15px;font-weight:850;line-height:1.4;margin-top:4px;white-space:pre-wrap}.dx-news-admin-note{font-size:12px;color:var(--muted);line-height:1.45}.dx-news-state{font-size:12px;margin-top:9px}.dx-news-ok{color:#9ff3c5}.dx-news-err{color:#ffc1cb}.dx-news-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.dx-news-preview{margin-top:12px;padding:12px;border-radius:14px;background:var(--navy2);border:1px solid #ffffff18}.dx-news-preview b{display:block;color:var(--yellow);font-size:10px;letter-spacing:.45px;margin-bottom:5px}@media(max-width:390px){.dx-news-actions{grid-template-columns:1fr}}`;document.head.appendChild(s)}
function ensureBanner(){style();const home=$('homePage');if(!home)return null;let b=$('dxNewsBanner');if(!b){b=document.createElement('section');b.id='dxNewsBanner';b.setAttribute('role','status');b.setAttribute('aria-live','polite');b.innerHTML='<div class="dx-news-label">📣 Dexter’s News</div><div class="dx-news-message" id="dxNewsMessage"></div>';home.prepend(b)}const top=home.querySelector('.work-top');if(top&&top.nextSibling!==b)top.after(b);else if(!top&&home.firstElementChild!==b)home.prepend(b);return b}
function ensureStaff(){style();const page=$('staffPage');if(!page)return null;let card=$('dxNewsAdminCard');if(card)return card;card=document.createElement('div');card.className='card hidden';card.id='dxNewsAdminCard';card.innerHTML='<h2>📣 News Alert</h2><p class="dx-news-admin-note">Publish a short message that appears at the top of the Dexter’s customer app. Staff can update or hide it at any time.</p><label>News message</label><textarea id="dxNewsInput" class="input" rows="4" maxlength="240" placeholder="Example: Dexter’s is hosting a Macmillan Coffee Morning on 23rd September."></textarea><div class="dx-news-actions"><button id="dxNewsSave" type="button" class="btn primary">Publish Alert</button><button id="dxNewsHide" type="button" class="btn secondary">Hide Alert</button></div><div class="dx-news-preview"><b>CURRENT CUSTOMER BANNER</b><span id="dxNewsPreview">No active news alert</span></div><div id="dxNewsAdminStatus" class="dx-news-state"></div>';page.appendChild(card);$('dxNewsSave').onclick=save;$('dxNewsHide').onclick=hide;return card}
async function loadCurrent(){const b=ensureBanner();if(!b)return;try{const d=await api('current');const text=String(d.message||'');const msg=$('dxNewsMessage'),preview=$('dxNewsPreview');if(msg)msg.textContent=text;b.classList.toggle('show',!!d.active&&!!text.trim());if(preview)preview.textContent=d.active&&text.trim()?text:'No active news alert';const input=$('dxNewsInput');if(input&&!input.matches(':focus'))input.value=text}catch(e){b.classList.remove('show');const preview=$('dxNewsPreview');if(preview)preview.textContent='Unable to load current alert'}}
function syncStaff(){const card=ensureStaff();if(!card)return;const r=role();card.classList.toggle('hidden',!(token()&&(r.includes('admin')||r.includes('staff'))))}
async function save(){const btn=$('dxNewsSave'),status=$('dxNewsAdminStatus'),message=$('dxNewsInput')?.value.trim()||'';if(!message){status.textContent='Type a news message first.';status.className='dx-news-state dx-news-err';return}btn.disabled=true;status.textContent='Publishing…';status.className='dx-news-state';try{await api('save',{message,active:true},true);status.textContent='✓ News alert published.';status.className='dx-news-state dx-news-ok';await loadCurrent()}catch(e){status.textContent=e.message;status.className='dx-news-state dx-news-err'}finally{btn.disabled=false}}
async function hide(){const btn=$('dxNewsHide'),status=$('dxNewsAdminStatus');btn.disabled=true;try{await api('unpublish',{},true);status.textContent='✓ News alert hidden.';status.className='dx-news-state dx-news-ok';await loadCurrent()}catch(e){status.textContent=e.message;status.className='dx-news-state dx-news-err'}finally{btn.disabled=false}}
function boot(){ensureBanner();ensureStaff();syncStaff();loadCurrent();setTimeout(()=>{ensureBanner();ensureStaff();syncStaff();loadCurrent()},900);new MutationObserver(()=>{ensureBanner();ensureStaff();syncStaff()}).observe(document.body,{childList:true,subtree:true});const rb=$('roleBadge');if(rb)new MutationObserver(syncStaff).observe(rb,{childList:true,characterData:true,subtree:true});setInterval(()=>{if(!document.hidden)loadCurrent()},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){syncStaff();loadCurrent()}})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();

(function(){
